-- Team draft 4/4 (epic #214, issue #218): Discord posts, spectator view,
-- analytics. Expand phase only, compatible with the previous app version
-- (rolling the app image back is safe; the database is not reverted):
--   * one new defaulted column, `draft.discord_posted_seq`: the highest
--     `draft_event.seq` already handed to the Discord poster. The poster
--     advances it after the transaction that wrote the events committed, so
--     an event is posted at most once. The previous app version never reads
--     or writes it.
--
-- Generated by drizzle-kit, then edited by hand: the column and the backfill
-- sit in one guarded block (a re-run is a no-op and can never move the cursor
-- back), and the CHECK constraint is added by hand (drizzle-kit 0.24 does not
-- emit CHECKs). The backfill sets the cursor of drafts that already exist to
-- their last event, so the deploy does not post history to Discord.

DO $$ BEGIN
 IF NOT EXISTS (
   SELECT 1 FROM information_schema.columns
   WHERE table_schema = 'public'
     AND table_name = 'bingoscape-next_draft'
     AND column_name = 'discord_posted_seq'
 ) THEN
   ALTER TABLE "bingoscape-next_draft" ADD COLUMN "discord_posted_seq" bigint DEFAULT 0 NOT NULL;
   UPDATE "bingoscape-next_draft" d
   SET "discord_posted_seq" = COALESCE(
     (SELECT max(e."seq") FROM "bingoscape-next_draft_event" e WHERE e."draft_id" = d."id"),
     0
   );
 END IF;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "bingoscape-next_draft" ADD CONSTRAINT "draft_discord_posted_seq_check" CHECK ("discord_posted_seq" >= 0);
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
